package struct FfiConverterTypeScriptBridge: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<ScriptBridge>()

    typealias FfiType = UInt64
    typealias SwiftType = ScriptBridge

    package static func lift(_ handle: UInt64) throws -> ScriptBridge {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ScriptBridgeImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    package static func lower(_ value: ScriptBridge) -> UInt64 {
         if let rustImpl = value as? ScriptBridgeImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    package static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ScriptBridge {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    package static func write(_ value: ScriptBridge, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


