package protocol Logger: AnyObject, Sendable {
    
    func log(level: LoggerEventLevel, event: String, message: String, parameters: [String: String]) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceLogger {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceLogger = UniffiVTableCallbackInterfaceLogger(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceLogger.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface Logger: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceLogger.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface Logger: handle missing in uniffiClone")
            }
        },
        log: { (
            uniffiHandle: UInt64,
            level: RustBuffer,
            event: RustBuffer,
            message: RustBuffer,
            parameters: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceLogger.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.log(
                     level: try FfiConverterTypeLoggerEventLevel_lift(level),
                     event: try FfiConverterString.lift(event),
                     message: try FfiConverterString.lift(message),
                     parameters: try FfiConverterDictionaryStringString.lift(parameters)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceLogger> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceLogger>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitLogger() {
    uniffi_nativeblocks_runtime_fn_init_callback_vtable_logger(UniffiCallbackInterfaceLogger.vtablePtr)
}

